// Configuração da demo: TODO e-mail vai só para DEMO_RECIPIENT.
const DEMO_RECIPIENT = 'voce@example.com';
const SERVICES = ['Lavagem detalhada', 'Polimento técnico', 'Vitrificação de pintura', 'Higienização interna', 'Película de proteção (PPF)', 'Revitalização de faróis'];

const body = $input.first().json.body ?? {};
if (typeof body.website === 'string' && body.website.trim()) {
  throw new Error("Spam descartado (honeypot).");
}
const s = (v) => (typeof v === 'string' ? v.trim() : '');
const lead = { name: s(body.name), phone: s(body.phone), email: s(body.email), service: s(body.service), message: s(body.message) };
const digits = lead.phone.replace(/\D/g, '').length;
const errors = [];
if (lead.name.length < 2 || lead.name.length > 80) errors.push('name');
if (digits < 10 || digits > 13) errors.push('phone');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(lead.email) || lead.email.length > 120) errors.push('email');
if (!SERVICES.includes(lead.service)) errors.push('service');
if (lead.message.length < 10 || lead.message.length > 1000) errors.push('message');
if (body.consent !== true) errors.push('consent');
if (errors.length) throw new Error('Campos inválidos: ' + errors.join(', '));

// Prompt injection: o pedido vai como JSON escapado dentro de <pedido>, tratado como dado.
const data = '<pedido>\n' + JSON.stringify({ nome: lead.name, servico: lead.service, mensagem: lead.message }, null, 2).replace(/</g, '\\u003c').replace(/>/g, '\\u003e') + '\n</pedido>';
return [{ json: { lead, data, demoRecipient: DEMO_RECIPIENT, receivedAt: new Date().toISOString() } }];

// Valida a saída da IA; se vier inválida ou a chamada falhar, usa 'morno'.
const prev = $('Validar e preparar').first().json;
const text = (($input.first().json.candidates ?? [])[0]?.content?.parts ?? []).filter((p) => !p.thought).map((p) => p.text ?? '').join('');
let temperatura = 'morno';
let justificativa = 'classificação indisponível';
try {
  const parsed = JSON.parse(text.slice(text.indexOf('{'), text.lastIndexOf('}') + 1));
  if (['quente', 'morno', 'frio'].includes(parsed.temperatura) && typeof parsed.justificativa === 'string' && parsed.justificativa.trim().length >= 3) {
    temperatura = parsed.temperatura;
    justificativa = parsed.justificativa.trim().slice(0, 240);
  }
} catch (e) {}
return [{ json: { ...prev, temperatura, justificativa } }];

// Usa o texto padrão se a IA falhar ou citar preço/prazo.
const prev = $('Interpretar classificação').first().json;
const first = prev.lead.name.split(' ')[0];
const fallback = `Olá, ${first}! Recebemos seu pedido de orçamento e obrigado pelo contato. Nossa equipe vai analisar e falar com você em breve para combinar uma avaliação. Equipe Lume.`;
const text = (($input.first().json.candidates ?? [])[0]?.content?.parts ?? []).filter((p) => !p.thought).map((p) => p.text ?? '').join('').trim().slice(0, 1200);
const risky = /R\$|\breais\b|\d+\s*(dias?|horas?|semanas?|min(utos)?|%)|\bdesconto/i;
const resposta = text.length < 20 || risky.test(text) ? fallback : text;
return [{ json: { ...prev, resposta } }];
